"use client";
/** Cross-origin vendor frame; no scripts execute in the private application document. */
export function TradingViewEmbed({kind,config,label}:{kind:'market-quotes'|'advanced-chart';config:Record<string,unknown>;label:string}){
 // URLs/configuration verified from the frames generated by the official embed snippets.
 const settings={...config,locale:'es',utm_source:'consultormacro.com',utm_medium:'widget_new',utm_campaign:kind};
 const src=`https://www.tradingview-widget.com/embed-widget/${kind}/?locale=es#${encodeURIComponent(JSON.stringify(settings))}`;
 return <div className="sector-embed"><iframe title={label} src={src} referrerPolicy="origin" sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox" style={{border:0,width:'100%',height:'calc(100% - 32px)'}}/><div className="tradingview-widget-copyright"><a href="https://www.tradingview.com/" target="_blank" rel="noopener nofollow">{label}</a> by TradingView</div></div>;
}
